Here's the entire Java program you can use and run:

```java
import java.io.BufferedWriter;
import java.io.FileWriter;
import java.io.IOException;
import java.util.Scanner;

public class PasswordGenerator {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter desired password length: ");
        int passwordLength = scanner.nextInt();

        if ((passwordLength < 8) || (passwordLength > 64)) {
            System.out.println("Password length must be between 8 and 64 characters. Please try again.");
            return;
        }

        String characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()-_=+[]{}|;:,.<>/?`~";
        StringBuilder password = new StringBuilder();
        password.setLength(passwordLength);

        for (int i = 0; i < passwordLength; i++) {
            int randomIndex = (int) (Math.random() * characters.length());
            password.setCharAt(i, characters.charAt(randomIndex));
        }

        System.out.println("Generated Password: " + password);

        System.out.print("Enter file name to save your password (include the .txt extension): ");
        String fileName = scanner.next();

        try (BufferedWriter writer = new BufferedWriter(new FileWriter(fileName))) {
            writer.write(password.toString());
            System.out.println("Password saved to the file '" + fileName + "'");
        } catch (IOException e) {
            System.out.println("An error occurred: " + e.getMessage());
        }

        scanner.close();
    }
}
```

