```javascript
/**
 * Calculates the Haversine distance between two geographical points given in
 * latitude and longitude coordinates. The distance is in miles by default.
 * 
 * @param {number} lat1 - Latitude of the first point as degrees between -90 and 90.
 * @param {number} lon1 - Longitude of the first point as degrees between -180 and 180.
 * @param {number} lat2 - Latitude of the second point as degrees between -90 and 90.
 * @param {number} lon2 - Longitude of the second point as degrees between -180 and 180.
 * @param {string} [unit='km'] - The unit of distance to return. Either 'km' (kilometers) or 'mi' (miles).
 * @returns {number} - The distance between two geographical points in requested unit of distance - kilometers (default) or miles (if specified).
 * @throws {Error} If any input parameter value is outside of its respective allowed, or if not valid for calculating distance (e.g., invalid latitude, longitude, or bad units for distance).
 */
function haversine(lat1, lon1, lat2, lon2, unit = 'km') {
    // Constants
    const RADIUS_Earth_km = 6371.0;
    const RADIUS_Earth_mi = 3958.8;

    // Validate latitude and longitude
    const isValidLatitude = lat1 >= -90 && lat1 <= 90;
    const isValidLongitude = lon1 >= -180 && lon1 <= 180;
    const isValidLat2 = lat2 >= -90 && lat2 <= 90;
    const isValidLon2 = lon2 >= -180 && lon2 <= 180;

    if (!isValidLatitude || !isValidLongitude || !isValidLat2 || !isValidLon2) {
        throw new Error('Invalid latitude or longitude value(s)!');
    }

    // Validate units for distance (only km is for Haversine formula, we will convert from km or mi to the other, if not in km, assume input to km is for miles and output to km is for km)
    if (!['km', 'mi'].includes(unit.toLowerCase())) {
        throw new Error('Invalid unit: please choose "km" or "mi"');
    }

    // Convert degrees to radians
    const rad = Math.PI / 180;
    const lat1Rad = lat1 * rad;
    const lon1Rad = lon1 * rad;
    const lat2Rad = lat2 * rad;
    const lon2Rad = lon2 * rad;

    // Difference in coordinates
    const deltaLat = lat2Rad - lat1Rad;
    const deltaLon = lon2Rad - lon1Rad;

    // Haversine formula
    const a = Math.pow(Math.sin(deltaLat / 2), 2) + Math.cos(lat1Rad) * Math.cos(lat2Rad) * Math.pow(Math.sin(deltaLon / 2), 2);
    const c = 2 * Math.asin(Math.sqrt(a));

    // Calculate distance - based off radius
    let result = RADIUS_Earth_km * c; // For kilometers
    if (unit === 'mi') { // Convert to miles if input/output units for distance = 'mi'
        result = RADIUS_Earth_mi * c; // For miles per function call, convert from 'km'
    }

    return result;
}

