#include <iostream>
#include <vector>
#include <numeric>
#include <cassert>

// Function to create and return all primes up to the number N
std::vector<int> sieveOfEratosthenes(int N) {
    std::vector<bool> is_prime(N+1, true); // Assume all numbers from 0 to N are prime.
    is_prime[0] = is_prime[1] = false; // 0 and 1 are not prime numbers.

    for (int current = 2; current * current <= N; ++current) {
        if (is_prime[current]) {
            for (int multiple = current * current; multiple <= N; multiple += current) {
                is_prime[multiple] = false; // Mark the multiples of "current" as not prime.
            }
        }
    }
    std::vector<int> primes;
    for (int i = 2; i <= N; ++i) {
        if (is_prime[i]) {
            primes.push_back(i); // Collect all prime numbers if they exist (from 2 to the root of N).
        }
    }
    return primes;
}

// Function to find the n-th prime number in a sieved list of primes
int nthPrime(int n, std::vector<int> primes) {
    return primes[n-1]; // The n-th prime is at index (n-1) in a 0-indexed list (0-based indexing).
}

int main() {
    int N = 100000; // Maximum number to iterate up the Sieve of Eratosthenes
    int n = 10; // We will look for 10th prime number, for instance. Change n as necessary. 

    // Create the list of primes up to the number N
    std::vector<int> primes = sieveOfEratosthenes(N);

    // Ensure the list of primes includes at least "n" primes
    assert(n <= static_cast<int>(primes.size()));

    // Find the n-th prime number in our list of primes
    int nthPrimeNumber = nthPrime(n, primes);

    // Output the result to the user
