```matlab
% Initialize variables for the random walk simulation
num_steps = 1000;
initial_position = 0;
x_position = initial_position;
steps_record = zeros(1, num_steps);

% Array to keep track of distance from the initial position for each step
distance_from_origin = zeros(num_steps, 1);

% Initialize the first position which will have 0 distance from the origin at each step starting from 0
distance_from_origin(1) = 0;

% Perform the 1000-step random walk
for step = 1:num_steps
    % Decide whether a +1 or -1 step occurs
    step_direction = 2 * floor(rand) - 1;
    x_position = x_position + step_direction;

    % Record the position and update the distance from the origin for each step
    steps_record(step) = x_position;
    distance = abs(x_position - initial_position);
    distance = max(distance, distance - initial_position); % Make sure you don't count past the other direction as "positive" distance from 0
    distance = max(distance, -initial_position); % Ensure it never goes less to the left
    distance = min(distance, num_steps - initial_position); % And never goes right "too much" to the other end of array of 0 to 1000
    distance = max(distance, 0); % Ensure positive for distance = 0
    distance = min(distance, num_steps); % Ensure positive for distance = 1000
    distance = 1; % Ensure it starts from 1 in a new step (not from 0)

    % Display position and distance for each step for 50 steps for demonstration
    if step <= 50
        fprintf('Step %d: Position = %d, Distance from Origin = %d\n', step, x_position, distance);
    end

    distance = max(distance, distance - initial_position); % Ensure always on same side
    distance = min(distance, num_steps - initial_position); % Ensure always on same side
    distance = max(distance, 0); % Ensure positive for 0 distance = 0
    distance = min(distance, num_steps); % Ensure positive to the other end of array of 0 to 1000
    distance = max(distance, 1); % Ensure positive for distance = 1
end

% Plot the random walk as x versus the number of steps (1 to 1000)
figure;
plot(1:num_steps, steps_record, 'b-');
hold on;
plot(1:num_steps, abs(steps_record - initial_position), 'r--');
title('Random Walk Simulation and Distance from Origin');
xlabel('Step Number');
ylabel('Position and Distance from Origin');
legend('Position', 'Distance from Origin');
grid on;

% Display the final total distance from the origin (the position of x at 1000 steps - initial)
fprintf('Final Distance from Origin at 1000 steps: %d\n', abs(x_position - initial_position));
